      } | {
        kind: "file-offset";
        offset: number;
      } | {
        kind: "file-offset-range";
        start: number;
        end: number;
      }>;
      evidence_links: string[];
    };
  };
  view: {
    kind: "summary";
  } | {
    kind: "facet";
    facet: "mitigations" | "linkage";
  } | {
    kind: "item";
    collection: "sections" | "symbols" | "modules";
    selector: {
      index: number;
    } | {
      /** Exact name used by this operation. */
      name: string;
    } | {
      /** Exact observed module path or original source-map reference from a module page; an empty reference is valid. */
      path: string;
    } | {
      node_id: string;
    };
  } | {
    kind: "page";
    collection: "sections" | "symbols" | "modules";
    offset: number;
    limit: number;
  } | {
    kind: "native";
    facet: "procedure" | "pseudocode" | "assembly" | "basic_blocks" | "comments" | "callers" | "callees" | "incoming_references" | "outgoing_references" | "unresolved_calls" | "referenced_strings" | "referenced_names" | "native_api" | "value_flow_summary" | "value_flow_operations" | "value_flow_def_use" | "value_flow_effects" | "value_flow_parameters" | "value_flow_parameter_uses";
