177:async function calcMd5(file, signal, onProg) {
178:    const spark = new SparkMD5.ArrayBuffer()
179:    const READ = 2 * 1024 * 1024
180:    for (let offset = 0; offset < file.size; offset += READ) {
181:        if (signal && signal.aborted) throw new Error('aborted')
182:        const end = Math.min(offset + READ, file.size)
183:        const buf = await file.slice(offset, end).arrayBuffer()
184:        spark.append(buf)
185:        onProg(end, file.size)
186:        await new Promise(r => setTimeout(r, 0))
187:    }
188:    return spark.end().toLowerCase()
189:}
